target.css:
:root {
  --ink: #24333c;
  --muted: #68767b;
  --paper: #fffdf7;
  --line: #d9ded5;
  --teal: #267b78;
  --teal-pale: #dcefed;
  --gold: #e5b94b;
  --gold-pale: #fff2ca;
}

.prop-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--teal);
  border-radius: 14px;
}

.card-header,
.title-wrap,
.card-footer {
  display: flex;
  align-items: center;
}

.card-header,
.card-footer {
  justify-content: space-between;
}

.title-wrap {
  gap: 10px;
}

.symbol {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--teal);
  background: var(--teal-pale);
  border-radius: 10px;
  font-size: 19px;
}

.eyebrow,
.holder-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.09em;
}

h1 {
  margin: 2px 0 0;
  font-size: 20px;
  line-height: 1.05;
}

.state {
  padding: 5px 8px;
  color: var(--teal);
  background: var(--teal-pale);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.07em;
}

.prop-summary {
  display: flex;
  justify-content: space-between;
  margin: 14px 0 12px;
  padding: 10px 12px;
  background: var(--gold-pale);
  border-radius: 8px;
  font-size: 13px;
}

.prop-summary strong {
  font-size: 14px;
}

.prop-summary span {
  color: var(--muted);
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.detail {
  padding: 9px 12px;
}

.detail + .detail {
  border-left: 1px solid var(--line);
}

dt {
  color: var(--muted);
  font-size: 11px;
}

dd {
  margin: 3px 0 0;
  font-size: 14px;
  font-weight: 700;
}

.card-footer {
  margin-top: 13px;
}

.holder {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.holder-name {
  font-size: 13px;
  font-weight: 600;
}

button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

